import React from 'react';
import type { Meta, StoryObj } from '@storybook/react-webpack5';
import { MemoryRouter } from 'react-router-dom';
import { expect, userEvent, within } from 'storybook/test';
import { ZimmColourSwatchGroup } from '.';
import type { ZimmColourSwatchValue } from '.';

/** Placeholder swatch fills — don't need to resolve to real products, just working image URLs. */
const swatchImage = (seed: string) => `https://picsum.photos/seed/zimm-colour-${seed}/400/600`;

const PRODUCT_HREF = '/womens/dresses/natura-mini-dress/8637DS241.html';

const BAY_BLUE: ZimmColourSwatchValue = {
  value: 'BAYBL',
  name: 'Bay Blue',
  href: `${PRODUCT_HREF}?color=BAYBL`,
  imageUrl: swatchImage('bay-blue'),
};
const IVORY: ZimmColourSwatchValue = {
  value: 'IVORY',
  name: 'Ivory',
  href: `${PRODUCT_HREF}?color=IVORY`,
  imageUrl: swatchImage('ivory'),
};
const BLACK: ZimmColourSwatchValue = {
  value: 'BLACK',
  name: 'Black',
  href: `${PRODUCT_HREF}?color=BLACK`,
  imageUrl: swatchImage('black'),
};
const ROSE_PINK: ZimmColourSwatchValue = {
  value: 'ROSE',
  name: 'Rose Pink',
  href: `${PRODUCT_HREF}?color=ROSE`,
  imageUrl: swatchImage('rose-pink'),
};
const EMERALD: ZimmColourSwatchValue = {
  value: 'EMER',
  name: 'Emerald',
  href: `${PRODUCT_HREF}?color=EMER`,
  imageUrl: swatchImage('emerald'),
};
const CORAL: ZimmColourSwatchValue = {
  value: 'CORAL',
  name: 'Coral',
  href: `${PRODUCT_HREF}?color=CORAL`,
  imageUrl: swatchImage('coral'),
};
/** No `imageUrl` — exercises AC 5's filter (an unpopulated index image is not rendered). */
const GOLD_UNPOPULATED: ZimmColourSwatchValue = { value: 'GOLD', name: 'Gold', href: `${PRODUCT_HREF}?color=GOLD` };
const NAVY_UNPOPULATED: ZimmColourSwatchValue = { value: 'NAVY', name: 'Navy', href: `${PRODUCT_HREF}?color=NAVY` };

const meta: Meta<typeof ZimmColourSwatchGroup> = {
  title: 'Commerce/ZimmColourSwatchGroup',
  component: ZimmColourSwatchGroup,
  argTypes: {
    label: { control: 'text' },
    selectedName: { control: 'text' },
    selectedValue: { control: 'text' },
  },
  decorators: [
    // Same reason as zimmColourSwatch/index.stories.tsx: this molecule composes
    // ZimmColourSwatch, which can render a react-router Link — no Router in
    // .storybook/preview.tsx.
    (Story: React.ComponentType) => (
      <MemoryRouter>
        <Story />
      </MemoryRouter>
    ),
  ],
};
export default meta;

type Story = StoryObj<typeof ZimmColourSwatchGroup>;

export const Default: Story = {
  args: {
    label: 'Colour',
    selectedName: BAY_BLUE.name,
    selectedValue: BAY_BLUE.value,
    values: [BAY_BLUE, IVORY, BLACK, ROSE_PINK],
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    const swatches = canvas.getAllByRole('radio');
    await expect(swatches).toHaveLength(4);

    const selected = canvas.getByRole('radio', { name: 'Bay Blue' });
    await expect(selected).toHaveAttribute('aria-checked', 'true');

    // Arrow-key focus movement across the swatches — moves focus only, never selection (see
    // index.tsx's own comment on why arrow presses don't call any change handler here).
    selected.focus();
    await expect(selected).toHaveFocus();
    await userEvent.keyboard('{ArrowRight}');
    await expect(canvas.getByRole('radio', { name: 'Ivory' })).toHaveFocus();
    await userEvent.keyboard('{ArrowLeft}');
    await expect(selected).toHaveFocus();
  },
};

export const SingleColour: Story = {
  name: 'Single colour — AC 1',
  args: {
    label: 'Colour',
    selectedName: BAY_BLUE.name,
    selectedValue: BAY_BLUE.value,
    values: [BAY_BLUE],
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    await expect(canvas.queryAllByRole('radio')).toHaveLength(0);
    await expect(canvas.getByTestId('colour-swatch-group')).toHaveTextContent('Colour: Bay Blue');
  },
};

export const WithUnpopulatedVariations: Story = {
  name: 'With unpopulated variations — AC 5',
  args: {
    label: 'Colour',
    selectedName: BAY_BLUE.name,
    selectedValue: BAY_BLUE.value,
    values: [BAY_BLUE, IVORY, BLACK, GOLD_UNPOPULATED, NAVY_UNPOPULATED],
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    await expect(canvas.getAllByRole('radio')).toHaveLength(3);
    await expect(canvas.queryByRole('radio', { name: 'Gold' })).not.toBeInTheDocument();
    await expect(canvas.queryByRole('radio', { name: 'Navy' })).not.toBeInTheDocument();
  },
};

export const NoneSelected: Story = {
  args: {
    label: 'Colour',
    values: [BAY_BLUE, IVORY, BLACK, ROSE_PINK],
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    const radios = canvas.getAllByRole('radio');
    const checked = radios.filter((radio) => radio.getAttribute('aria-checked') === 'true');
    await expect(checked).toHaveLength(0);
    // No selection: the first rendered swatch is the one in the roving tab order.
    await expect(radios[0]).toHaveAttribute('tabindex', '0');
  },
};

export const Paginated: Story = {
  args: {
    label: 'Colour',
    selectedName: IVORY.name,
    selectedValue: IVORY.value,
    values: [BAY_BLUE, IVORY, BLACK, ROSE_PINK, EMERALD, CORAL],
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);

    // Page 1 of 2 (4 + 2): the selected colour is on this first page, so its checked state is
    // visible immediately.
    await expect(canvas.getAllByRole('radio')).toHaveLength(4);
    await expect(canvas.getByRole('radio', { name: 'Ivory' })).toHaveAttribute('aria-checked', 'true');

    const prev = canvas.getByRole('button', { name: /previous colours/i });
    await expect(prev).toBeDisabled();

    await userEvent.click(canvas.getByRole('button', { name: /next colours/i }));

    // Window advanced to the remaining 2 colours — the first page's colours are gone.
    await expect(canvas.getAllByRole('radio')).toHaveLength(2);
    await expect(canvas.queryByRole('radio', { name: 'Bay Blue' })).not.toBeInTheDocument();
    await expect(canvas.getByRole('button', { name: /next colours/i })).toBeDisabled();

    await userEvent.click(canvas.getByRole('button', { name: /previous colours/i }));

    // Back on page 1: the previously-selected swatch is visible again and still checked — paging
    // moves the window only, never the selection.
    await expect(canvas.getByRole('radio', { name: 'Ivory' })).toHaveAttribute('aria-checked', 'true');
  },
};

