 */
import React from 'react';
import { describe, test, expect, vi } from 'vitest';
import { render, screen } from '@testing-library/react';
import { ChakraProvider } from '@chakra-ui/react';
import { MemoryRouter } from 'react-router-dom';
import { IntlProvider } from 'react-intl';
import theme from 'app/theme';
import { ZimmColourSwatchGroup } from './index';
import type { ZimmColourSwatchValue } from './index';

vi.mock('../../atoms/zimmIcon', () => ({ ZimmIcon: () => null }));

const IMAGE = (seed: string) => `https://picsum.photos/seed/zimm-colour-${seed}/400/600`;

const BAY_BLUE: ZimmColourSwatchValue = {
  value: 'BAYBL',
  name: 'Bay Blue',
  href: '/p.html?color=BAYBL',
  imageUrl: IMAGE('bay-blue'),
};
const IVORY: ZimmColourSwatchValue = {
  value: 'IVORY',
  name: 'Ivory',
  href: '/p.html?color=IVORY',
  imageUrl: IMAGE('ivory'),
};
const BLACK: ZimmColourSwatchValue = {
  value: 'BLACK',
  name: 'Black',
  href: '/p.html?color=BLACK',
  imageUrl: IMAGE('black'),
};
/** No `imageUrl` — exercises AC 5's filter. */
const ROSE_UNPOPULATED: ZimmColourSwatchValue = { value: 'ROSE', name: 'Rose Pink', href: '/p.html?color=ROSE' };
const GOLD_UNPOPULATED: ZimmColourSwatchValue = { value: 'GOLD', name: 'Gold', href: '/p.html?color=GOLD' };

const renderGroup = (props: Partial<React.ComponentProps<typeof ZimmColourSwatchGroup>> = {}) =>
  render(
    <ChakraProvider theme={theme}>
      <IntlProvider locale="en-AU" defaultLocale="en-AU">
        <MemoryRouter>
          <ZimmColourSwatchGroup label="Colour" values={[BAY_BLUE, IVORY, BLACK]} {...props} />
        </MemoryRouter>
      </IntlProvider>
    </ChakraProvider>,
  );

describe('ZimmColourSwatchGroup', () => {
  test('renders the label only, with no radios, when exactly one colour is populated (AC 1)', () => {
    renderGroup({ selectedName: 'Bay Blue', selectedValue: 'BAYBL', values: [BAY_BLUE] });
    expect(screen.queryAllByRole('radio')).toHaveLength(0);
    expect(screen.getByTestId('colour-swatch-group')).toHaveTextContent('Colour: Bay Blue');
  });

  test('renders one radio swatch per populated colour', () => {
    renderGroup({ values: [BAY_BLUE, IVORY, BLACK] });
    expect(screen.getAllByRole('radio')).toHaveLength(3);
  });

  test('marks exactly the swatch matching selectedValue as checked', () => {
    renderGroup({ selectedName: 'Ivory', selectedValue: 'IVORY', values: [BAY_BLUE, IVORY, BLACK] });
    const checked = screen.getAllByRole('radio').filter((radio) => radio.getAttribute('aria-checked') === 'true');
    expect(checked).toHaveLength(1);
    expect(checked[0]).toHaveAccessibleName('Ivory');
  });

  test('AC 5: filters out colours whose index image is not populated', () => {
    const { container } = renderGroup({ values: [BAY_BLUE, IVORY, BLACK, ROSE_UNPOPULATED, GOLD_UNPOPULATED] });
    expect(screen.getAllByRole('radio')).toHaveLength(3);
    expect(container.textContent).not.toContain('Rose Pink');
    expect(container.textContent).not.toContain('Gold');
  });

  test('AC 5 filters on image population only, never a stock/orderability-like field', () => {
    // This component's own prop type carries no stock field at all — the extra property below
    // proves the filter cannot be keying on one, since there is nowhere in the type for it to
    // come from other than this deliberately-bolted-on test fixture.
    const valueWithExtraField: ZimmColourSwatchValue & { orderable: boolean } = { ...BAY_BLUE, orderable: false };
    renderGroup({ values: [valueWithExtraField, IVORY] });
    expect(screen.getByRole('radio', { name: 'Bay Blue' })).toBeInTheDocument();
  });

  test('collapses to the label-only branch when only one of several colours is populated', () => {
    renderGroup({
      selectedName: 'Bay Blue',
      selectedValue: 'BAYBL',
      values: [BAY_BLUE, ROSE_UNPOPULATED, GOLD_UNPOPULATED],
    });
    expect(screen.queryAllByRole('radio')).toHaveLength(0);
  });

  test('keeps exactly one swatch in the roving tab order at a time', () => {
    renderGroup({ selectedName: 'Ivory', selectedValue: 'IVORY', values: [BAY_BLUE, IVORY, BLACK] });
    const tabbable = screen.getAllByRole('radio').filter((radio) => radio.getAttribute('tabindex') === '0');
    expect(tabbable).toHaveLength(1);
  });

  test('resolves its recipe under a ChakraProvider — registered, not silently inherited', () => {
    renderGroup({ values: [BAY_BLUE, IVORY, BLACK] });
    // The only detection anywhere for this recipe losing its entry in theme/components/index.ts
    // — same reasoning as zimmProductMeta/index.test.tsx's own equivalent test. Measured as the
    // literal var() declaration, not a resolved px value: jsdom's getComputedStyle does not
    // substitute a custom property (see zimmColourSwatch/index.test.tsx's own note on this).
    const styles = window.getComputedStyle(screen.getByTestId('colour-swatch-group'));
    expect(styles.gap).toBe('var(--zimm-scale-xs)');
  });
});

