import React from 'react';
import { describe, test, expect, vi } from 'vitest';
import { render, screen } from '@testing-library/react';
import { ChakraProvider } from '@chakra-ui/react';
import { MemoryRouter } from 'react-router-dom';
import { IntlProvider } from 'react-intl';
import theme from 'app/theme';
import { ZimmColourSwatchGroup } from './index';
import type { ZimmColourSwatchValue } from './index';

vi.mock('../../atoms/zimmIcon', () => ({ ZimmIcon: () => null }));

const IMAGE = (seed: string) => `https://picsum.photos/seed/zimm-colour-${seed}/400/600`;

const makeValue = (value: string, name: string): ZimmColourSwatchValue => ({
  value,
  name,
  href: `/p.html?color=${value}`,
  imageUrl: IMAGE(value),
});

const SIX_VALUES: ZimmColourSwatchValue[] = [
  makeValue('C1', 'Colour One'),
  makeValue('C2', 'Colour Two'),
  makeValue('C3', 'Colour Three'),
  makeValue('C4', 'Colour Four'),
  makeValue('C5', 'Colour Five'),
  makeValue('C6', 'Colour Six'),
];

const renderGroup = (props: Partial<React.ComponentProps<typeof ZimmColourSwatchGroup>> = {}) =>
  render(
    <ChakraProvider theme={theme}>
      <IntlProvider locale="en-AU" defaultLocale="en-AU">
        <MemoryRouter>
          <ZimmColourSwatchGroup label="Colour" values={SIX_VALUES} {...props} />
        </MemoryRouter>
      </IntlProvider>
    </ChakraProvider>,
  );

describe('PROBE: initial-mount page vs selectedValue location (6 populated, selected = 6th)', () => {
  test('reports what actually renders on mount', () => {
    renderGroup({ selectedName: 'Colour Six', selectedValue: 'C6' });

    const radios = screen.getAllByRole('radio');
    const names = radios.map((r) => r.getAttribute('aria-label'));
    const checked = radios.filter((r) => r.getAttribute('aria-checked') === 'true');
    const tabbable = radios.filter((r) => r.getAttribute('tabindex') === '0');

    // eslint-disable-next-line no-console
    console.log('PROBE rendered radio count:', radios.length);
    // eslint-disable-next-line no-console
    console.log('PROBE rendered radio names (aria-label):', JSON.stringify(names));
    // eslint-disable-next-line no-console
    console.log('PROBE checked count:', checked.length, JSON.stringify(checked.map((r) => r.getAttribute('aria-label'))));
    // eslint-disable-next-line no-console
    console.log('PROBE tabbable (tabindex=0) count:', tabbable.length, JSON.stringify(tabbable.map((r) => r.getAttribute('aria-label'))));

    // Assertions phrased as "what the hypothesis predicts" so a pass here means the hypothesis
    // is CONFIRMED, and a failure means the component actually handles it correctly.
    expect(radios).toHaveLength(4); // page 1 of 2, items 0-3, NOT the page containing C6
    expect(names).toEqual(['Colour One', 'Colour Two', 'Colour Three', 'Colour Four']);
    expect(checked).toHaveLength(0); // nothing visible is marked selected
    expect(tabbable).toHaveLength(0); // nothing visible is keyboard-reachable
  });
});
