import React from 'react';
import { describe, test, expect, vi } from 'vitest';
import { render, screen } from '@testing-library/react';
import { ChakraProvider } from '@chakra-ui/react';
import { MemoryRouter } from 'react-router-dom';
import { IntlProvider } from 'react-intl';
import theme from 'app/theme';
import { ZimmColourSwatchGroup } from './index';
import type { ZimmColourSwatchValue } from './index';

vi.mock('../../atoms/zimmIcon', () => ({ ZimmIcon: () => null }));

const IMAGE = (seed: string) => `https://picsum.photos/seed/zimm-colour-${seed}/400/600`;
const makeValue = (value: string, name: string): ZimmColourSwatchValue => ({
  value, name, href: `/p.html?color=${value}`, imageUrl: IMAGE(value),
});

const renderGroup = (values: ZimmColourSwatchValue[]) =>
  render(
    <ChakraProvider theme={theme}>
      <IntlProvider locale="en-AU" defaultLocale="en-AU">
        <MemoryRouter>
          <ZimmColourSwatchGroup label="Colour" values={values} />
        </MemoryRouter>
      </IntlProvider>
    </ChakraProvider>,
  );

describe('PROBE 4: boundary — exactly 4 vs 5 populated colours', () => {
  test('exactly 4 populated: no pagination controls at all', () => {
    const four = [1, 2, 3, 4].map((n) => makeValue(`C${n}`, `Colour ${n}`));
    renderGroup(four);
    expect(screen.getAllByRole('radio')).toHaveLength(4);
    expect(screen.queryByRole('button', { name: /next colours/i })).not.toBeInTheDocument();
    expect(screen.queryByRole('button', { name: /previous colours/i })).not.toBeInTheDocument();
  });

  test('exactly 5 populated: page 1 is 4, page 2 is exactly 1', async () => {
    const five = [1, 2, 3, 4, 5].map((n) => makeValue(`C${n}`, `Colour ${n}`));
    renderGroup(five);
    expect(screen.getAllByRole('radio')).toHaveLength(4);
    expect(screen.getByRole('button', { name: /next colours/i })).toBeInTheDocument();
  });
});
